const queryVector = $('Embed câu hỏi').first().json.embedding.values;
const userQuery = $('Webhook Chatbot').first().json.body.query;

function cosineSimilarity(a, b) {
  let dot = 0, nA = 0, nB = 0;
  const len = Math.min(a.length, b.length);
  for (let i = 0; i < len; i++) {
    dot += a[i] * b[i];
    nA += a[i] * a[i];
    nB += b[i] * b[i];
  }
  if (nA === 0 || nB === 0) return 0;
  return dot / (Math.sqrt(nA) * Math.sqrt(nB));
}

const scored = items
  .filter(i => i.json.embedding && Array.isArray(i.json.embedding))
  .map(i => ({
    text: i.json.text,
    filename: i.json.metadata ? i.json.metadata.filename : 'unknown',
    score: cosineSimilarity(queryVector, i.json.embedding)
  }))
  .sort((a, b) => b.score - a.score)
  .slice(0, 5);

const context = scored.map(d => `[Nguồn: ${d.filename}] ${d.text}`).join('\n\n---\n\n');

return [{
  json: {
    query: userQuery,
    context,
    sources: scored.map(d => ({ filename: d.filename, score: Math.round(d.score * 1000) / 1000 }))
  }
}];

